import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const A=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/FLIP.md","filePath":"manual-zh/FLIP.md","lastUpdated":1785684581000}'),o={name:"manual-zh/FLIP.md"};function s(c,t,n,i,p,h){return e(),r("div",null,[...t[0]||(t[0]=[a(`<h3 id="_12-5-flip" tabindex="-1">12.5 FLIP <a class="header-anchor" href="#_12-5-flip" aria-label="Permalink to &quot;12.5 FLIP&quot;">​</a></h3><pre><code>FLIP /VARIABLES=var_list /NEWNAMES=var_name.
</code></pre><p><code>FLIP</code> 转置活动数据集中的行和列。它使个案与变量互换，反之亦然。</p><p>转置后的活动数据集中的所有变量都是数值型的。字符串变量在转置后的文件中取系统缺失值。</p><p>不需要子命令即可运行。如果指定了 <code>VARIABLES</code> 子命令，则选择要转换为个案的变量，未指定的变量将被丢弃。如果省略 <code>VARIABLES</code> 子命令，则选择所有变量进行转置。</p><p>由 <code>NEWNAMES</code> 指定的变量（必须是字符串变量）用于为 <code>FLIP</code> 创建的变量命名。仅使用该变量的前 8 个字符。如果未指定 <code>NEWNAMES</code>，则默认使用名为 <strong>CASE_LBL</strong> 的变量（如果存在）。如果不存在，则 <code>FLIP</code> 创建的变量命名为 VAR000 到 VAR999，然后是 VAR1000、VAR1001，依此类推。</p><p>当有可用的 <code>NEWNAMES</code> 变量时，名称必须先规范化才能成为变量名。无效字符在第一位置替换为字母 ‘V’，在后续位置替换为 ‘_’。如果由此生成的名称不唯一，则添加数字扩展，从 1 开始，直到找到唯一名称或没有剩余可能性。如果发生后者，则 <code>FLIP</code> 操作中止。</p><p>结果字典包含一个 <strong>CASE_LBL</strong> 变量，即宽度为 8 的字符串变量，用于存储转置前字典中变量的名称。超过 8 个字符的变量名会被截断。如果再次对此数据集调用 <code>FLIP</code>，可以将 <strong>CASE_LBL</strong> 变量传递给 <code>NEWNAMES</code> 子命令以重新创建原始变量名。</p><p><code>FLIP</code> 遵循 <code>N OF CASES</code>（见 <a href="./N-OF-CASES">N OF CASES</a>）。它忽略 <code>TEMPORARY</code>（见 <a href="./TEMPORARY">TEMPORARY</a>），因此“临时”转换变为永久。</p><h4 id="_12-5-1-flip-示例" tabindex="-1">12.5.1 FLIP 示例 <a class="header-anchor" href="#_12-5-1-flip-示例" aria-label="Permalink to &quot;12.5.1 FLIP 示例&quot;">​</a></h4><p>在示例 12.5 中，使用 <code>DATA LIST</code>（见 <a href="./DATA-LIST">DATA LIST</a>）输入数据，使得数据集中的第一个变量是包含该个案其他数据描述的字符串变量。显然这种安排不便于执行统计分析，因此如果当初更仔细地考虑数据应如何排列会更好。然而数据通常由第三方来源提供，您无法控制其形式。幸运的是，我们可以使用 <code>FLIP</code> 来交换活动数据集中的变量和个案。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data list notable list /heading (a16) v1 v2 v3 v4 v5 v6 begin data. date-of-birth 1970 1989 2001 1966 1976 1982 sex 1 0 0 1 0 1 score 10 10 9 3 8 9 end data.  echo &#39;Before FLIP:&#39;. display variables. list.  flip /variables = all /newnames = heading.  echo &#39;After FLIP:&#39;. display variables. list.</span></span></code></pre></div><p><strong>示例 12.5：</strong> 使用 <code>FLIP</code> 交换数据集中的变量和个案</p><p>如结果 12.3 所示，在 <code>FLIP</code> 命令运行之前有七个变量（六个包含数据，一个用于标题）和三个个案。之后有四个变量（每个个案一个，加上 <strong>CASE_LBL</strong> 变量）和六个个案。如果不需要，您可以删除 <strong>CASE_LBL</strong> 变量（见 <a href="./DELETE-VARIABLES">DELETE VARIABLES</a>）。</p><table tabindex="0"><thead><tr><th>名称</th><th>v1</th><th>v2</th><th>v3</th><th>v4</th><th>v5</th><th>v6</th></tr></thead><tbody><tr><td>名称</td><td>位置</td><td>打印格式</td><td>写入格式</td><td></td><td></td><td></td></tr><tr><td>heading</td><td>1</td><td>A16</td><td>A16</td><td></td><td></td><td></td></tr><tr><td>v1</td><td>2</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>v2</td><td>3</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>v3</td><td>4</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>v4</td><td>5</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>v5</td><td>6</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>v6</td><td>7</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>date-of-birth</td><td>1970.00</td><td>1989.00</td><td>2001.00</td><td>1966.00</td><td>1976.00</td><td>1982.00</td></tr><tr><td>sex</td><td>1.00</td><td>.00</td><td>.00</td><td>1.00</td><td>.00</td><td>1.00</td></tr><tr><td>score</td><td>10.00</td><td>10.00</td><td>9.00</td><td>3.00</td><td>8.00</td><td>9.00</td></tr><tr><td>名称</td><td>位置</td><td>打印格式</td><td>写入格式</td><td></td><td></td><td></td></tr><tr><td>CASE_LBL</td><td>1</td><td>A8</td><td>A8</td><td></td><td></td><td></td></tr><tr><td>date_of_birth</td><td>2</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>sex</td><td>3</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>score</td><td>4</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>CASE_LBL</td><td>date_of_birth</td><td>sex</td><td>score</td><td></td><td></td><td></td></tr><tr><td>v1</td><td>1970.00</td><td>1.00</td><td>10.00</td><td></td><td></td><td></td></tr><tr><td>v2</td><td>1989.00</td><td>.00</td><td>10.00</td><td></td><td></td><td></td></tr><tr><td>v3</td><td>2001.00</td><td>.00</td><td>9.00</td><td></td><td></td><td></td></tr><tr><td>v4</td><td>1966.00</td><td>1.00</td><td>3.00</td><td></td><td></td><td></td></tr><tr><td>v5</td><td>1976.00</td><td>.00</td><td>8.00</td><td></td><td></td><td></td></tr><tr><td>v6</td><td>1982.00</td><td>1.00</td><td>9.00</td><td></td><td></td><td></td></tr></tbody></table><p><strong>结果 12.3：</strong> 使用 <code>FLIP</code> 交换数据集中的变量和个案的结果</p>`,16)])])}const L=d(o,[["render",s]]);export{A as __pageData,L as default};
